use num_complex::Complex;

fn real_if_close(arr: Vec<Complex<i32>>, tol: i32) -> Vec<Complex<i32>> {
    // If array is empty, return it as-is
    if arr.is_empty() {
        return arr;
    }
    
    // Check if all elements have imaginary part close to zero
    let all_close = arr.iter().all(|c| {
        let imag_abs = c.im.abs();
        imag_abs <= tol * 2
    });
    
    if all_close {
        // Create new array with imaginary parts set to 0
        arr.into_iter()
            .map(|c| Complex::new(c.re, 0))
            .collect()
    } else {
        // Return original array unchanged
        arr
    }
}